# DK RAP.  Randers - Randers Privb
#
let rr = path("d3.dk.rap");

with detail = 4, railway = :first :pax :removed {
    with link = "line.dk.RAP" {
        track(
                rr[:ran.yh - 0.1dl, :ran.yh] << 2.5mo
            ..  rr[:ran.xh, :ran.xh + 0.16km]
        );
        line_label(:right:nw, rr[:ran.xh + 0.15km] >> 0.5mt, "RAP");
        track(rr[:ran.xh + 0.14km, :rap.yr]);
    }
}

